begin;
alter table public.ai_runs drop constraint if exists ai_runs_operation_check;
alter table public.ai_runs add constraint ai_runs_operation_check check(operation in ('qualification','company_research','outreach_generation','outreach_draft','follow_up_generation','reply_classification','meeting_brief_generation','meeting_brief','proposal_generation','proposal_draft'));
create table public.meeting_discovery_outcomes(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id),meeting_id uuid not null,lead_id uuid not null,company_id uuid,conversation_id uuid not null,current_situation text,problem_statement text,desired_outcome text,explicit_facts jsonb not null default '[]',requested_features jsonb not null default '[]',technical_context text,existing_stack jsonb not null default '[]',timeline text,urgency text,budget_status text not null check(budget_status in ('UNKNOWN','DISCLOSED','RANGE_DISCLOSED','NOT_DISCLOSED','NOT_APPLICABLE')),budget_amount numeric,budget_currency text,budget_range_min numeric,budget_range_max numeric,decision_process text,decision_maker text,stakeholders jsonb not null default '[]',constraints jsonb not null default '[]',risks jsonb not null default '[]',unknowns jsonb not null default '[]',next_step text,recorded_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(workspace_id,id),unique(workspace_id,meeting_id),foreign key(workspace_id,meeting_id) references public.meetings(workspace_id,id),foreign key(workspace_id,lead_id) references public.leads(workspace_id,id),foreign key(workspace_id,company_id) references public.companies(workspace_id,id),foreign key(workspace_id,conversation_id) references public.conversations(workspace_id,id));
create table public.proposals(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id),lead_id uuid not null,company_id uuid,meeting_id uuid not null,discovery_outcome_id uuid not null,version integer not null check(version>0),generation_key text not null,status text not null check(status in ('draft','ready_for_review','approved','rejected')),title text not null,executive_summary text not null,problem_statement text not null,proposed_solution text not null,scope jsonb not null,deliverables jsonb not null,exclusions jsonb not null,assumptions jsonb not null,timeline text,milestones jsonb not null,pricing jsonb not null,client_responsibilities jsonb not null,acceptance_criteria jsonb not null,unknowns jsonb not null,next_step text not null,confidence numeric(5,4) not null check(confidence between 0 and 1),needs_review boolean not null default false,warnings jsonb not null default '[]',provider text not null,model text not null,prompt_version text not null,approved_at timestamptz,approved_by uuid references auth.users(id),rejected_at timestamptz,rejection_reason text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(workspace_id,generation_key),unique(workspace_id,meeting_id,version),foreign key(workspace_id,lead_id) references public.leads(workspace_id,id),foreign key(workspace_id,company_id) references public.companies(workspace_id,id),foreign key(workspace_id,meeting_id) references public.meetings(workspace_id,id),foreign key(workspace_id,discovery_outcome_id) references public.meeting_discovery_outcomes(workspace_id,id));
create index proposals_review_idx on public.proposals(workspace_id,status,created_at desc);create index proposals_lead_idx on public.proposals(workspace_id,lead_id,version desc);
alter table public.meeting_discovery_outcomes enable row level security; alter table public.proposals enable row level security;
create policy discovery_member_access on public.meeting_discovery_outcomes for all to authenticated using(workspace_id in(select workspace_id from public.workspace_members where user_id=(select auth.uid()))) with check(workspace_id in(select workspace_id from public.workspace_members where user_id=(select auth.uid())));
create policy proposals_member_access on public.proposals for all to authenticated using(workspace_id in(select workspace_id from public.workspace_members where user_id=(select auth.uid()))) with check(workspace_id in(select workspace_id from public.workspace_members where user_id=(select auth.uid())));
grant select,insert,update on public.meeting_discovery_outcomes,public.proposals to authenticated;
commit;
